 * implemented against the generic syntax rather than any scheme-specific
 * grammar (`http`, `mailto`, etc. are all handled the same way).
 */

/** Raised for a malformed input; its message becomes the tail of a CLI error line. */
export class UriError extends Error {}

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

const UNRESERVED = /^[A-Za-z0-9\-._~]$/

/**
 * Splits the leading `scheme:` off a URI reference. The scheme ends at the
 * first `:` that is not preceded by a `/`, `?` or `#`; if such a `:` never
 * appears before one of those three characters (or at all), there is no
 * scheme.
 */
function splitScheme(str) {
  for (let i = 0; i < str.length; i++) {
    const c = str[i]
    if (c === ':') return { scheme: str.slice(0, i), rest: str.slice(i + 1) }
    if (c === '/' || c === '?' || c === '#') break
  }
  return { scheme: null, rest: str }
}

/** Splits a leading `//authority` off what remains after the scheme. */
function splitAuthority(str) {
  if (!str.startsWith('//')) return { authorityPresent: false, authority: null, rest: str }
  let i = 2
  while (i < str.length && str[i] !== '/' && str[i] !== '?' && str[i] !== '#') i++
  return { authorityPresent: true, authority: str.slice(2, i), rest: str.slice(i) }
}

/**
 * Splits an authority into userinfo, host and port. The userinfo is
 * everything before the last `@`; the port is everything after the first
 * `:` that follows the last `]` (so an IPv6 literal's own colons are not
 * mistaken for the host/port separator).
 */
function splitAuthorityParts(authority) {
  let userinfo = null
  let hostport = authority
  const at = authority.lastIndexOf('@')
  if (at !== -1) {
    userinfo = authority.slice(0, at)
    hostport = authority.slice(at + 1)
  }
  const bracket = hostport.lastIndexOf(']')
  const colon = hostport.indexOf(':', bracket + 1)
  let host = hostport
  let port = null
  if (colon !== -1) {
    host = hostport.slice(0, colon)
    port = hostport.slice(colon + 1)
  }
  return { userinfo, host, port }
}

/**
 * Parses a URI reference into its generic-syntax components. Absent and
 * empty are distinct for the authority, query and fragment: `null` means
 * absent, a string (possibly `''`) means present.
 */
export function parseUri(str) {
  const { scheme, rest: r1 } = splitScheme(str)
  const { authorityPresent, authority, rest: r2 } = splitAuthority(r1)
  const m = r2.match(/^([^?#]*)(\?[^#]*)?(#.*)?$/s)
  const path = m[1]
  const query = m[2] !== undefined ? m[2].slice(1) : null
  const fragment = m[3] !== undefined ? m[3].slice(1) : null
  let userinfo = null
  let host = null
  let port = null
  if (authorityPresent) ({ userinfo, host, port } = splitAuthorityParts(authority))
  return { scheme, authorityPresent, userinfo, host, port, path, query, fragment }
}

/** Uppercases the two hex digits of every `%XX` and decodes it when the byte it names is unreserved. */
function normalizePercent(str, componentName) {
  let out = ''
  for (let i = 0; i < str.length; i++) {
    const c = str[i]
    if (c !== '%') {
      out += c
      continue
    }
    const digits = str.slice(i + 1, i + 3)
    if (!/^[0-9A-Fa-f]{2}$/.test(digits)) {
      throw new UriError(`the ${componentName} has a truncated percent-encoding`)
    }
    const upper = digits.toUpperCase()
    const ch = String.fromCharCode(parseInt(upper, 16))
    out += UNRESERVED.test(ch) ? ch : `%${upper}`
    i += 2
  }
  return out
}

function asciiLower(str) {
  let out = ''
  for (const c of str) {
    const code = c.codePointAt(0)
    out += code >= 0x41 && code <= 0x5a ? String.fromCharCode(code + 0x20) : c
  }
  return out
}

/** Removes `.` and `..` segments from a path per RFC 3986 section 5.2.4. */
function removeDotSegments(path) {
  const output = []
  let input = path
  while (input !== '') {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = `/${input.slice(3)}`
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = `/${input.slice(4)}`
      output.pop()
    } else if (input === '/..') {
      input = '/'
      output.pop()
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      const m = input.match(/^\/?[^/]*/)
      let segment = m[0]
      if (segment === '') {
        segment = input
        input = ''
      } else {
        input = input.slice(segment.length)
      }
      output.push(segment)
    }
  }
  return output.join('')
}

/**
 * Normalizes an already-parsed URI reference: lowercases the scheme,
 * normalizes percent-encodings in every component (checking for truncation
 * in the order path, userinfo, host, query, fragment), lowercases the host,
 * drops a default or empty port, removes dot segments from the path, and
 * forces an empty path to `/` when an authority is present.
 */
export function normalizeComponents(c) {
  const scheme = c.scheme !== null ? asciiLower(c.scheme) : null
  const path = normalizePercent(c.path, 'path')
  const userinfo = c.userinfo !== null ? normalizePercent(c.userinfo, 'userinfo') : null
  const host = c.host !== null ? normalizePercent(c.host, 'host') : null
  const query = c.query !== null ? normalizePercent(c.query, 'query') : null
  const fragment = c.fragment !== null ? normalizePercent(c.fragment, 'fragment') : null

  const lowerHost = host !== null ? asciiLower(host) : null

  let port = c.port
  if (port !== null) {
    const defaultPort = scheme !== null ? DEFAULT_PORTS[scheme] : undefined
    if (port === '' || port === defaultPort) port = null
  }

  let finalPath = removeDotSegments(path)
  if (c.authorityPresent && finalPath === '') finalPath = '/'

  return {
    scheme,
    authorityPresent: c.authorityPresent,
    userinfo,
    host: lowerHost,
    port,
    path: finalPath,
    query,
    fragment,
  }
