/** Serializes normalized components back into a URI reference string. */
export function serialize(c) {
  let s = ''
  if (c.scheme !== null) s += `${c.scheme}:`
  if (c.authorityPresent) {
    s += '//'
    if (c.userinfo !== null) s += `${c.userinfo}@`
    if (c.host !== null) s += c.host
    if (c.port !== null) s += `:${c.port}`
  }
  s += c.path
  if (c.query !== null) s += `?${c.query}`
  if (c.fragment !== null) s += `#${c.fragment}`
  return s
}

/** Merges a relative reference path onto a base path per RFC 3986 section 5.2.3. */
function mergePaths(base, refPath) {
  if (base.authorityPresent && base.path === '') return `/${refPath}`
  const idx = base.path.lastIndexOf('/')
  if (idx === -1) return refPath
  return base.path.slice(0, idx + 1) + refPath
}

/**
 * Resolves a parsed reference against a parsed base per RFC 3986 section
 * 5.2.2, strict form (a reference that repeats the base's scheme is still
 * treated as absolute). Returns unnormalized components; the caller is
 * expected to normalize the result.
 */
export function resolveComponents(base, ref) {
  let scheme
  let authorityPresent
  let userinfo
  let host
  let port
  let path
  let query

  if (ref.scheme !== null) {
    scheme = ref.scheme
    authorityPresent = ref.authorityPresent
    userinfo = ref.userinfo
    host = ref.host
    port = ref.port
    path = ref.path
    query = ref.query
  } else {
    scheme = base.scheme
    if (ref.authorityPresent) {
      authorityPresent = true
      userinfo = ref.userinfo
      host = ref.host
      port = ref.port
      path = ref.path
      query = ref.query
    } else {
      authorityPresent = base.authorityPresent
      userinfo = base.userinfo
      host = base.host
      port = base.port
      if (ref.path === '') {
        path = base.path
        query = ref.query !== null ? ref.query : base.query
      } else {
        path = ref.path.startsWith('/') ? ref.path : mergePaths(base, ref.path)
        query = ref.query
      }
    }
  }

  return { scheme, authorityPresent, userinfo, host, port, path, query, fragment: ref.fragment }
}
